/**
 * Map geometry (generated by tools/map/build.ts) and the land mask for instant pin feedback.
 * Both are loaded only when a map is shown, so they are not part of the main bundle.
 */
import maskUrl from '../../../../shared/data/landmask.bin?url';

export interface Country {
  readonly id: string;
  readonly name: string;
  readonly area: number;
  readonly d: string;
  readonly label: readonly [number, number] | null;
}

export interface MapData {
  readonly viewBox: readonly [number, number, number, number];
  readonly countries: readonly Country[];
  readonly lakes: string;
}

let data: Promise<MapData> | undefined;

export function loadMapData(): Promise<MapData> {
  data ??= import('./europe.json').then((module) => module.default as unknown as MapData);
  return data;
}

let mask: Promise<Uint8Array> | undefined;

/** The server's check is authoritative (SPEC 12.3). */
export function landMask(): Promise<Uint8Array> {
  mask ??= fetch(maskUrl)
    .then((response) => response.arrayBuffer())
    .then((buffer) => new Uint8Array(buffer));
  return mask;
}
